SELECT 
FROM t_i18n_release
WHERE application_id = #{applicationId} AND release_no = #{releaseNo}

SELECT MAX(release_no)
FROM t_i18n_release
WHERE application_id = #{applicationId}

SELECT MAX(release_no)
FROM t_i18n_release
WHERE application_id = #{applicationId} AND release_no < #{releaseNo}

SELECT 
FROM t_i18n_release
WHERE application_id = #{applicationId}
ORDER BY release_no DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM t_i18n_release
WHERE application_id = #{applicationId}

