UPDATE t_i18n_release
SET status = 'READY', ready_time = #{now}, update_time = #{now}
WHERE release_id = #{releaseId} AND status = 'PENDING_CHECK'

UPDATE t_i18n_release
SET status = 'FAILED', failure_reason = #{reason}, update_time = #{now}
WHERE release_id = #{releaseId} AND status = 'PENDING_CHECK'
